            case "debit":
                System.out.println("Processing debit payment type");
                System.out.println("Verifying security code: " + securityCode);
                this.status = "paid";
                break;
            case "credit":
                System.out.println("Processing credit payment type");
                System.out.println("Verifying security code: " + securityCode);
                this.status = "paid";
                break;
            default:
